9	
10	// buildCorrectionLandmarksMap 构造一份做过校正的地图：t=100 帧两次观测 L、
11	// t=200 帧观测 L 和 M、t=300 帧无观测；校正 c1 覆盖 t=100..300，路标
12	// 出现列表恰为 {L/1, M/1}（L 在范围内被三帧次/同帧多条观测涉及仍只记
13	// 一条）。
14	func buildCorrectionLandmarksMap(t *testing.T, path string) {
15		t.Helper()
16		m, err := Create(path, baseConfig())
17		if err != nil {
18			t.Fatal(err)
19		}
20		if _, err := m.ImportSegment(Segment{ID: "s1", Frames: []Frame{
21			{Time: 100, DX: 1, Observations: []Observation{{ID: "L"}, {ID: "L"}}},
22			{Time: 200, DX: 1, Observations: []Observation{{ID: "L"}, {ID: "M"}}},
23			{Time: 300, DX: 1},
24		}}); err != nil {
25			t.Fatal(err)
26		}
27		if _, err := m.Correct(Correction{ID: "c1", Anchor: 100, Target: CorrectionTarget{X: 5, Y: 6, Variance: 1}}); err != nil {
28			t.Fatal(err)
29		}
30		if err := m.Close(); err != nil {
31			t.Fatal(err)
32		}
33	}
34	
35	// 未篡改的文件正常打开，路标列表与提交顺序、内容保持不变。
36	func TestOpenCorrectionLandmarkListAccepted(t *testing.T) {
37		path := filepath.Join(t.TempDir(), "m.pose")
38		buildCorrectionLandmarksMap(t, path)
39		m, err := Open(path)
40		if err != nil {
41			t.Fatalf("open: %v", err)
42		}
43		defer m.Close()
44		recs, err := m.Corrections()
45		if err != nil {
46			t.Fatal(err)
47		}
48		if len(recs) != 1 {
49			t.Fatalf("records = %+v", recs)
50		}
51		lms := recs[0].Landmarks
52		if len(lms) != 2 || lms[0].ID != "L" || lms[0].Occurrence != 1 ||
53			lms[1].ID != "M" || lms[1].Occurrence != 1 {
54			t.Fatalf("landmark changes = %+v", lms)
55		}
56	}
57	
58	// 即使长度与校验和都有效，路标列表少记、多记、重复或错指出现编号，Open
59	// 都必须以 ErrCorrupt 拒绝整份文件、不返回可用地图且原文件不变。
60	func TestOpenRejectsBadCorrectionLandmarkList(t *testing.T) {
61		cases := []struct {
62			name string
63			fn   func(fd *fileData)
64		}{
65			{"missing affected occurrence", func(fd *fileData) {
66				// 删掉 L/1：范围内 L 被多次观测却没有记录。
67				fd.Corrections[0].Landmarks = fd.Corrections[0].Landmarks[1:]
68			}},
69			{"missing other landmark", func(fd *fileData) {
70				// 删掉 M/1。
71				fd.Corrections[0].Landmarks = fd.Corrections[0].Landmarks[:1]
72			}},
73			{"duplicate occurrence entry", func(fd *fileData) {
74				// L/1 重复写两条（坐标、次数都合法也不行）。
75				lcs := fd.Corrections[0].Landmarks
76				fd.Corrections[0].Landmarks = append([]landmarkChangeJSON{lcs[0]}, lcs...)
77			}},
78			{"unknown landmark id", func(fd *fileData) {
79				lcs := fd.Corrections[0].Landmarks
80				extra := lcs[0]
81				extra.ID = "GHOST"
82				fd.Corrections[0].Landmarks = append(lcs, extra)
83			}},
84			{"nonexistent occurrence number", func(fd *fileData) {
85				// 范围只涉及 L/1：改写成不存在的 L/3。
86				fd.Corrections[0].Landmarks[0].Occurrence = 3
87			}},
88			{"empty list while range has observations", func(fd *fileData) {
89				fd.Corrections[0].Landmarks = nil
90			}},
91		}
92		for _, tc := range cases {
93			t.Run(tc.name, func(t *testing.T) {
94				path := filepath.Join(t.TempDir(), "m.pose")
95				buildCorrectionLandmarksMap(t, path)
96				tamperFile(t, path, tc.fn)
97				assertOpenCorrupt(t, path)
98			})
99		}
100	}
101	
102	// 范围内没有任何路标观测时，空列表合法；同一份记录被写入非空列表必须拒绝。
103	func TestOpenCorrectionEmptyRangeList(t *testing.T) {
104		path := filepath.Join(t.TempDir(), "m.pose")
105		m, err := Create(path, baseConfig())
106		if err != nil {
107			t.Fatal(err)
108		}
109		// t=100 观测 L，但校正锚点取无观测的 t=200：范围 [200,200] 无观测。
110		if _, err := m.ImportSegment(Segment{ID: "s1", Frames: []Frame{
111			{Time: 100, DX: 1, Observations: []Observation{{ID: "L"}}},
112			{Time: 200, DX: 1},
113		}}); err != nil {
114			t.Fatal(err)
115		}
116		if _, err := m.Correct(Correction{ID: "c1", Anchor: 200, Target: CorrectionTarget{X: 9, Y: 9, Variance: 1}}); err != nil {
117			t.Fatal(err)
118		}
119		if err := m.Close(); err != nil {
120			t.Fatal(err)
121		}
122	
123		// 合法：空列表。
124		m2, err := Open(path)
125		if err != nil {
126			t.Fatalf("open with empty list: %v", err)
127		}
128		recs, _ := m2.Corrections()
129		if len(recs) != 1 || len(recs[0].Landmarks) != 0 {
130			t.Fatalf("landmarks = %+v, want empty", recs)
131		}
132		if err := m2.Close(); err != nil {
133			t.Fatal(err)
134		}
135	
136		// 非空列表必须拒绝，且文件保持不变。
137		tamperFile(t, path, func(fd *fileData) {
138			fd.Corrections[0].Landmarks = []landmarkChangeJSON{{
139				ID: "L", Occurrence: 1,
140				Before: Landmark{ID: "L", X: 2, Y: 2, Count: 1},
141				After:  Landmark{ID: "L", X: 2, Y: 2, Count: 1},
142			}}
143		})
144		assertOpenCorrupt(t, path)
145	}
146	
147	// 校正没有改变某次出现的位置（恒等校正）：范围内有它的观测，列表仍必须
148	// 保留对应记录；删掉仍要拒绝。
149	func TestOpenIdentityCorrectionKeepsObservedOccurrence(t *testing.T) {
150		path := filepath.Join(t.TempDir(), "m.pose")
151		m, err := Create(path, baseConfig())
152		if err != nil {
153			t.Fatal(err)
154		}
155		// t=100 位姿 (2,2)、方差 0.5；以该位姿为目标做恒等校正，范围含 L 观测。
156		if _, err := m.ImportSegment(Segment{ID: "s1", Frames: []Frame{
157			{Time: 100, DX: 1, Observations: []Observation{{ID: "L", X: 1}}},
158		}}); err != nil {
159			t.Fatal(err)
160		}
161		rec, err := m.Correct(Correction{ID: "c1", Anchor: 100, Target: CorrectionTarget{X: 2, Y: 2, Variance: 0.5}})
162		if err != nil {
163			t.Fatal(err)
164		}
165		if len(rec.Landmarks) != 1 || rec.Landmarks[0].Before.X != rec.Landmarks[0].After.X {
166			t.Fatalf("identity record = %+v", rec)
167		}
168		if err := m.Close(); err != nil {
169			t.Fatal(err)
170		}
171		m2, err := Open(path)
172		if err != nil {
173			t.Fatalf("open identity correction: %v", err)
174		}
175		m2.Close()
176	
177		tamperFile(t, path, func(fd *fileData) {
178			fd.Corrections[0].Landmarks = nil
179		})
180		assertOpenCorrupt(t, path)
181	}
182	
183	// 记录结束帧之后追加的帧不属于范围：新帧观测的路标出现既不能被要求记录，
184	// 也不能被额外写入列表。
185	func TestOpenCorrectionRangeExcludesAppendedFrames(t *testing.T) {
186		path := filepath.Join(t.TempDir(), "m.pose")
187		buildCorrectionLandmarksMap(t, path)
188	
189		// 校正后再导入 t=400 观测新路标 N：c1 仍只覆盖到 t=300，合法。
190		m, err := Open(path)
191		if err != nil {
192			t.Fatal(err)
193		}
194		if _, err := m.ImportSegment(Segment{ID: "s2", Frames: []Frame{
195			{Time: 400, DX: 1, Observations: []Observation{{ID: "N"}}},
196		}}); err != nil {
197			t.Fatal(err)
198		}
199		if err := m.Close(); err != nil {
200			t.Fatal(err)
201		}
202		m2, err := Open(path)
203		if err != nil {
204			t.Fatalf("reopen with appended frame: %v", err)
205		}
206		m2.Close()
207	
208		// 把范围外才出现的 N/1 写进旧记录：必须拒绝。
209		tamperFile(t, path, func(fd *fileData) {
210			lcs := fd.Corrections[0].Landmarks
211			extra := lcs[0]
212			extra.ID = "N"
213			fd.Corrections[0].Landmarks = append(lcs, extra)
214		})
215		assertOpenCorrupt(t, path)
216	}
